// HasValueTexts applies the HasEdge predicate on the "value_texts" edge.
func HasValueTexts() predicate.Attribute {
	return predicate.Attribute(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ValueTextsTable, ValueTextsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasValueTextsWith applies the HasEdge predicate on the "value_texts" edge with a given conditions (other predicates).
func HasValueTextsWith(preds ...predicate.ValueText) predicate.Attribute {
	return predicate.Attribute(func(s *sql.Selector) {
		step := newValueTextsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

